opencat.script:
var T = ctx.timeline();
var O2=5.2, O3=8.4, O4=9.3, O5=12.3, O6=16.1, O7=18.5, O8=21.0, O9=23.0, O10=25.6;

/* ── helpers ─────────────────────────────────────────────────────── */
// typewriter: reveal `msg` char-by-char (linear) over [t0,t0+dur]
function tw(id, msg, t0, dur, ease) {
  var n = ctx.getNode(id);
  var d = { set: function(v){ n.text(msg.slice(0, Math.round(v.opacity))); } };
  T.fromTo(d, { opacity: 0 }, { opacity: msg.length, duration: dur, ease: ease || 'none' }, t0);
}
// per-char soft reveal: chars pop in on a power3.out curve, then settle
function rev(id, t0, dur) {
  var parts = ctx.splitText(id, { type: 'chars' });
  var N = parts.length;
  T.set(id, { opacity: 0 }, 0);
  T.set(id, { opacity: 1 }, t0);
  for (var i = 0; i < N; i++) {
    var local = (i + 1) / N;
    T.set(parts[i], { opacity: 1 }, t0 + dur * local * local);
  }
  var settle = { set: function(){ for (var j = 0; j < N; j++) parts[j].set({ opacity: 1 }); } };
  T.set(settle, { opacity: 1 }, t0 + dur);
}
// similar for non-node targets resolved by id list
function reveal(el, t) { T.fromTo(el, { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: .3, ease: 'power3.out' }, t); }

/* ════════════ ROOT — cross-fades (§2.2) ════════════ */
T.set(['s-prscroll','s-hard','s-summarize','s-useskill','s-fcode','s-fflow','s-fdisc','s-fcredits','s-cta'], { opacity: 0 }, 0);
function xfade(a, b, t, d) {
  // Reference unmounts the outgoing scene instantly at its window end, so
  // the light #F0EFE9 root shows through during the incoming fade-in (the
  // old scene is NOT cross-faded out). Mirror with an instant set.
  T.set(a, { opacity: 0 }, t);
  T.fromTo(b, { opacity: 0 }, { opacity: 1, duration: d, ease: 'power1.inOut' }, t);
}
T.to('s-opener', { scale: 1.6, opacity: 0, filter: 'blur(8px)', duration: 0.4, ease: 'power2.in', transformOrigin: '66% 59%' }, 4.8);
T.set('s-opener', { opacity: 0 }, 5.22);
T.set('s-prscroll', { opacity: 1 }, 5.2);
T.fromTo('s-prscroll', { opacity: 0 }, { opacity: 1, duration: 0.3, ease: 'power2.out' }, 5.15);
xfade('s-prscroll', 's-hard',      8.4,  0.28);
xfade('s-hard',     's-summarize', 9.3,  0.28);
xfade('s-summarize','s-useskill',  12.3, 0.28);
xfade('s-useskill', 's-fcode',     16.1, 0.35);
xfade('s-fcode',    's-fflow',     18.5, 0.3);
xfade('s-fflow',    's-fdisc',     21.0, 0.3);
xfade('s-fdisc',    's-fcredits',  23.0, 0.3);
xfade('s-fcredits', 's-cta',       25.6, 0.35);
// pknob left：ref 为 %（相对 ptrack）。ptrack 宽 = pwin 1228.8 − pctrl px 2×28.8
//   − pplay 28.8 − gap 2×23 − ptime min-width 172.8 = 923.6px（各场景同构），
//   引擎 inset 动画仅 px（mutations.rs inset_left:f32），故 % × 923.6 落 px。
//   ref: feature-code.html:104/123、feature-flow.html:151/172、
//   feature-discussion.html:152/171、feature-credits.html:108/131
T.set('fc-pfill', { scaleX: .05 }, 0); T.set('fc-pknob', { left: (5 / 100) * 923.6 }, 0);
T.set('ff-pfill', { scaleX: .22 }, 0); T.set('ff-pknob', { left: (22 / 100) * 923.6 }, 0);
T.set('fd-pfill', { scaleX: .66 }, 0); T.set('fd-pknob', { left: (66 / 100) * 923.6 }, 0);
T.set('cr-pfill', { scaleX: .86 }, 0); T.set('cr-pknob', { left: (86 / 100) * 923.6 }, 0);
T.set('auto220', { scale: .61 }, 0); T.set('auto327', { scale: .61 }, 0);
T.set('auto328', { scale: .84 }, 0); T.set('auto374', { scale: .61 }, 0); T.set('auto421', { scale: .61 }, 0);

/* ════════════ SCENE 1 — opener ════════════ */
// ref opener.html:108 dM1 = m1.offsetHeight + GAP(30.72): m1 rows 43.008 + 54.528
// (prlink inline-block margin box) = 97.536 → Chrome offsetHeight 98 → dM1 = 128.72.
T.set('op-stack', { y: 128.72 }, 0);
T.set('op-win', { left: 0, top: 0, width: 1920, height: 1080, borderRadius: 0 }, 0);
T.set('op-composer', { left: 540, width: 840, bottom: 370, scale: 1.85, transformOrigin: '50% 100%' }, 0);
T.to('op-win', { left: 160, top: 102.6, width: 1599.36, height: 874.8, borderRadius: 25.92, duration: .55, ease: 'power2.inOut' }, 2.55);
// ref opener.html:134-138 drives the morph through one eased p and composes
// per frame: s=1.85-0.85p, vw=1554-85.2p, w=vw/s, left=W/2-w/2,
// bottom=370-304.72p — w=vw/s is nonlinear in p, so tween the proxy, not
// the layout props independently.
var morph = { set: function(v){
  var p = v.opacity, s = 1.85 - 0.85 * p, vw = 1554 - 85.2 * p, w = vw / s, W = 1920 - 320.64 * p;
  var c = ctx.getNode('op-composer');
  c.left(W / 2 - w / 2); c.width(w); c.bottom(370 - 304.72 * p); c.scale(s);
} };
T.fromTo(morph, { opacity: 0 }, { opacity: 1, duration: .55, ease: 'power2.inOut' }, 2.55);
T.fromTo('op-input', { x: 280, opacity: 0 }, { x: 0, opacity: 1, duration: .55, ease: 'power3.out' }, 0.02);
T.fromTo('op-chips', { x: 340, opacity: 0 }, { x: 0, opacity: 1, duration: .55, ease: 'power3.out' }, 0.10);
T.fromTo('op-meta',  { x: 340, opacity: 0 }, { x: 0, opacity: 1, duration: .55, ease: 'power3.out' }, 0.16);
T.to('op-orb', { rotation: 360, duration: 1.0, ease: 'none', repeat: 4 }, 0);
T.to('op-caret', { opacity: 0, duration: .4, ease: 'steps(1)', repeat: 1, yoyo: true }, 0.1);
T.set('op-caret', { opacity: 1 }, 0.6);
tw('op-typed', "Someone on our team just opened a PR for a new pr-to-video skill — can you review it?", 0.6, 1.5, 'none');
// ref opener.html:102-108,117: retX/retY = ↵ center − (0.21,0.14)·CUR(105.6)
// = (−22.2,−14.8). ↵ center in this port's full-bleed composer measures
// (1714,578) → anchor (1691.8,563.2); rises from +300 like the ref.
T.fromTo('op-cursor', { x: 1691.8, y: 863.2, opacity: 0 }, { y: 563.2, opacity: 1, duration: .7, ease: 'power3.out' }, 1.3);
T.to('op-cursor', { scale: .84, duration: .1, ease: 'power2.in', transformOrigin: '21% 14%' }, 2.3);
T.to('op-cursor', { scale: 1, duration: .18, ease: 'power2.out', transformOrigin: '21% 14%' }, 2.4);
T.fromTo('op-ret', { color: '#6F6E66' }, { color: '#D97757', duration: .08, ease: 'power1.in' }, 2.35);
T.to('op-ret', { color: '#6F6E66', duration: .25 }, 2.5);
T.set({ set: function(){ ctx.getNode('op-typed').text(''); } }, { opacity: 1 }, 2.5);
T.set({ set: function(){ ctx.getNode('op-caret').opacity(0); } }, { opacity: 1 }, 2.5);
T.fromTo('op-bar', { opacity: 0, x: -14 }, { opacity: 1, x: 0, duration: .3, ease: 'power2.out' }, 2.85);
T.to('op-chips', { opacity: 0, height: 0, duration: .3, ease: 'power2.in' }, 2.6);
T.fromTo('op-m1', { opacity: 0 }, { opacity: 1, duration: .3, ease: 'power2.out' }, 3.2);
T.to('op-stack', { y: 0, duration: .45, ease: 'power3.out' }, 3.2);
// ref opener.html:109-110: linkX/linkY = prlink center − (22.2,14.8);
// this port's prlink centers at (1365,634) with feed bottom 316.8 → (1342.8,619.2).
T.to('op-cursor', { x: 1342.8, y: 619.2, duration: .6, ease: 'power3.inOut' }, 3.5);
T.to('op-cursor', { scale: .84, duration: .1, ease: 'power2.in' }, 4.2);
T.to('op-cursor', { scale: 1, duration: .18, ease: 'power2.out' }, 4.3);
T.fromTo('op-prlink', { color: '#D97757' }, { color: '#F2A98C', duration: .1 }, 4.22);
T.to('op-prlink', { color: '#D97757', duration: .3 }, 4.42);
T.set('op-ripple', { left: 1365 - 48, top: 634 - 48, scale: 0, opacity: 0 }, 4.22);
T.to('op-ripple', { scale: 1.1, opacity: .5, duration: .2, ease: 'power2.out' }, 4.22);
T.to('op-ripple', { scale: 1.9, opacity: 0, duration: .32, ease: 'power2.out' }, 4.42);
T.to({ set: function(v){} }, { opacity: 1, duration: .2 }, 5.0);

/* ════════════ SCENE 2 — pr-scroll ════════════ */
T.fromTo('prs-browser', { scale: 1.04, opacity: 0 }, { scale: 1, opacity: 1, duration: .4, ease: 'power3.out' }, O2);
T.set('prs-inner', { filter: 'blur(0px)' }, O2);
reveal('prs-head', O2 + 0.5);
reveal('prs-head2', O2 + 0.5);
T.to('prs-tab0', { textColor: '#1f2328', duration: .05 }, O2 + 0.25);
T.to('prs-tab1', { textColor: '#1f2328', duration: .05 }, O2 + 0.95);
T.to('prs-tab2', { textColor: '#1f2328', duration: .05 }, O2 + 1.15);
for (var i = 0; i < 6; i++) {
  T.fromTo('prs-r' + (i + 1), { opacity: 0, x: 16 }, { opacity: 1, x: 0, duration: .18, ease: 'power2.out' }, O2 + 0.3 + i * 0.12);
}
T.to('prs-review', { opacity: 0, duration: .2 }, O2 + 1.1);
T.to('prs-files', { opacity: 1, duration: .2 }, O2 + 1.15);
T.to('prs-inner', { y: -3600, duration: 1.7, ease: 'power2.in' }, O2 + 1.2);
T.fromTo('prs-inner', { filter: 'blur(0px)' }, { filter: 'blur(2px)', duration: 1.1, ease: 'power2.in' }, O2 + 1.5);
reveal('prs-s1', O2 + 1.2); T.set('prs-cr1', { opacity: 1 }, O2 + 1.35); tw('prs-files-n', "629", O2 + 1.35, .45, 'none');
reveal('prs-s2', O2 + 1.75); T.set('prs-cr2', { opacity: 1 }, O2 + 1.9); tw('prs-lines-n', "87,291", O2 + 1.9, .7, 'none');
reveal('prs-s3', O2 + 2.35); T.set('prs-cr3', { opacity: 1 }, O2 + 2.5); tw('prs-commits-n', "4", O2 + 2.5, .2, 'none');
T.to('prs-cr1', { opacity: 0, duration: .25, ease: 'steps(1)', repeat: 1, yoyo: true }, O2 + 1.35 + .45);
T.to('prs-cr2', { opacity: 0, duration: .25, ease: 'steps(1)', repeat: 1, yoyo: true }, O2 + 1.9 + .7);
T.to('prs-cr3', { opacity: 0, duration: .25, ease: 'steps(1)', repeat: 1, yoyo: true }, O2 + 2.5 + .2);

/* ════════════ SCENE 3 — hard-read ════════════ */
T.fromTo('hr-txt', { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: .28, ease: 'power3.out' }, O3);

/* ════════════ SCENE 4 — summarize ════════════ */
T.set('sm-composer', { scale: 1.85, transformOrigin: '50% 100%' }, 0);
T.to('sm-orb', { rotation: 360, duration: 1, ease: 'none', repeat: 2 }, O4);
tw('sm-typed', "summarize this PR", O4, 0.8, 'none');
T.set('sm-caret', { opacity: 0 }, O4 + 0.82);
T.to('sm-composer', { y: -44, opacity: 0, duration: .32, ease: 'power2.in' }, O4 + 0.85);
T.to('sm-feed', { opacity: 1, duration: .25, ease: 'power1.out' }, O4 + 0.92);
// dist = inner.offsetHeight - feed.offsetHeight + 30 (summarize.html:80), margin-collapse
// layout, no wrapped row (ref render f315 shows every .al single-line): float innerH =
// headl 31.68*1.7 + 6*h 26.88*1.7 + 15*al 29.76*1.7 + collapsed gaps (6*23.04 + 15*11.52)
// = 1397.952; #sm-inner is absolutely positioned (= BFC root) so the last .al's own
// margin-bottom 11.52 does NOT collapse out and counts into the parent height:
// 1397.952+11.52 = 1409.472 → offsetHeight rounds to 1409 (CSSOM offsetHeight is an
// integer). feedH 849.6 rounds to 850. dist = 1409-850+30 = 589 (verified against Chrome
// layout of the reference composition).
T.fromTo('sm-inner', { y: 0 }, { y: -589, duration: 1.25, ease: 'power1.in' }, O4 + 1.0);
T.to('sm-veil', { opacity: 1, duration: .3, ease: 'power2.in' }, O4 + 2.2);
T.fromTo('sm-still', { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: .32, ease: 'power3.out' }, O4 + 2.32);

/* ════════════ SCENE 5 — use-skill ════════════ */
// ref use-skill.html:66 dCmd = cmd.offsetHeight + GAP(26.88), dOut = out.offsetHeight + 26.88:
// cmd row = 25.92*1.4 = 36.288 → offsetHeight 36; out = think(1.303*30.72=40.032) + mb 19.2
// + l0(27.84*1.45=40.368) = 99.6 → offsetHeight 100. y0 = dCmd+dOut = 189.76 (below the fold).
T.set('us-stack', { y: 189.76 }, 0);
T.to('us-orb', { rotation: 360, duration: 1, ease: 'none', repeat: 3 }, O5);
T.to('us-caret', { opacity: 0, duration: .5, ease: 'steps(1)', repeat: 1, yoyo: true }, O5 + 0.1);
T.set('us-ph', { opacity: 0 }, O5 + 0.4);
T.set('us-caret', { opacity: 1 }, O5 + 0.4);
tw('us-typed', "use pr-to-video to make a video for this pr", O5 + 0.4, 1.4, 'none');
T.set('us-caret', { opacity: 0 }, O5 + 2.0);
T.fromTo('us-cmd', { opacity: 0 }, { opacity: 1, duration: .3, ease: 'power2.out' }, O5 + 2.05);
// ref use-skill.html:73 — mid state parks the stack at y = dOut = 100+26.88 = 126.88
// (cmd visible above the feed floor, out still clipped).
T.to('us-stack', { y: 126.88, duration: .4, ease: 'power3.out' }, O5 + 2.05);
T.fromTo('us-out', { opacity: 0 }, { opacity: 1, duration: .2 }, O5 + 2.45);
T.to('us-stack', { y: 0, duration: .4, ease: 'power3.out' }, O5 + 2.5);
T.fromTo('us-think', { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: .3, ease: 'power2.out' }, O5 + 2.5);
T.to('us-ast', { rotation: 360, duration: 1.0, ease: 'none', repeat: 1 }, O5 + 2.5);
T.fromTo('us-l0', { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: .35, ease: 'power3.out' }, O5 + 3.0);

/* ════════════ SCENES 6–9 — feature cards (compressed inner time) ════════════ */
function cardTitle(id, caret, title, off, dur, signed) {
  tw(id, title, off + 0.3 / signed, dur / signed, 'none');
  T.to(caret, { opacity: 0, duration: .4, ease: 'steps(1)', repeat: 9, yoyo: true }, off + 0.3 / signed);
  T.to(caret, { opacity: 0, duration: .3, ease: 'power2.in' }, off + 4.5 / signed);
}
// feature-code (timeScale 2.0)
cardTitle('fc-ttext', 'fc-tcaret', "SHOW YOUR CODE", O6, 1.15, 2.0);
T.fromTo('fc-pwin', { opacity: 0, scale: .62, y: 10 }, { opacity: 1, scale: 1, y: 0, duration: .6 / 2, ease: 'power3.out' }, O6 + 0.15 / 2);
T.to('fc-codeview', { opacity: 1, duration: .45 / 2, ease: 'power2.out' }, O6 + 1.0 / 2);
T.to('fc-pfill', { scaleX: .11, duration: 3.2 / 2, ease: 'none' }, O6 + 1.4 / 2);
T.to('fc-pknob', { left: (11 / 100) * 923.6, duration: 3.2 / 2, ease: 'none' }, O6 + 1.4 / 2);
// ref feature-code.html:125: t2 2→5 dur 3.2 @1.4 (inner ×2), Math.floor
for (var tk = 3; tk <= 5; tk++) { (function(tk) {
  T.set({ set: function(){ ctx.getNode('fc-ptime').text('0:0' + tk + ' / 0:32'); } }, { opacity: 1 }, O6 + (1.4 + 3.2 * (tk - 2) / 3) / 2.0);
})(tk); }
T.to('fc-nonkeyA', { opacity: .32, duration: .4 / 2, ease: 'power2.out' }, O6 + 2.45 / 2);
T.to('fc-nonkeyB', { opacity: .32, duration: .4 / 2, ease: 'power2.out' }, O6 + 2.45 / 2);
T.to('fc-band', { opacity: 1, duration: .4 / 2, ease: 'power2.out' }, O6 + 2.5 / 2);
// feature-flow (2.56)
cardTitle('ff-ttext', 'ff-tcaret', "SHOW YOUR FEATURE", O7, 1.15, 2.56);
T.fromTo('ff-pwin', { opacity: 0, scale: .62, y: 10 }, { opacity: 1, scale: 1, y: 0, duration: .6 / 2.56, ease: 'power3.out' }, O7 + 0.15 / 2.56);
T.to('ff-pfill', { scaleX: .42, duration: 3.6 / 2.56, ease: 'none' }, O7 + 1.9 / 2.56);
T.to('ff-pknob', { left: (42 / 100) * 923.6, duration: 3.6 / 2.56, ease: 'none' }, O7 + 1.9 / 2.56);
// ref feature-flow.html:174: t2 7→13 dur 3.6 @1.9 (inner ×2.56), Math.floor
for (var fk = 8; fk <= 13; fk++) { (function(fk) {
  T.set({ set: function(){ ctx.getNode('ff-ptime').text('0:' + fk + ' / 0:32'); } }, { opacity: 1 }, O7 + (1.9 + 3.6 * (fk - 7) / 6) / 2.56);
})(fk); }
T.fromTo('ff-diff', { opacity: 0, x: -30, scale: .95 }, { opacity: 1, x: 0, scale: 1, duration: .5 / 2.56, ease: 'power3.out' }, O7 + 2.0 / 2.56);
T.fromTo('ff-a1', { opacity: 0, x: -10 }, { opacity: 1, x: 0, duration: .35 / 2.56, ease: 'power2.out' }, O7 + 2.55 / 2.56);
for (var c = 1; c <= 5; c++) {
  T.to('#ff-fc' + c, { opacity: 1, y: 0, scale: 1, duration: .4 / 2.56, ease: 'back.out(1.6)' }, O7 + 2.7 / 2.56 + (c - 1) * (0.1 / 2.56));
}
T.to('ff-striplbl', { opacity: 1, duration: .4 / 2.56, ease: 'power2.out' }, O7 + 3.0 / 2.56);
T.fromTo('ff-a2', { opacity: 0, x: -10 }, { opacity: 1, x: 0, duration: .35 / 2.56, ease: 'power2.out' }, O7 + 3.45 / 2.56);
T.fromTo('ff-video', { opacity: 0, scale: .8, x: 20 }, { opacity: 1, scale: 1, x: 0, duration: .55 / 2.56, ease: 'back.out(1.6)' }, O7 + 3.6 / 2.56);
T.fromTo('ff-vring', { opacity: .5, scale: 1 }, { opacity: 0, scale: 1.8, duration: 1.0 / 2.56, ease: 'power2.out', repeat: 1 }, O7 + 4.1 / 2.56);
// feature-discussion (outer 2.05, conversation 2x)
tw('fd-ttext', "SHOW YOUR REVIEW", O8 + 0.2 / 2.05, 0.9 / 2.05, 'none');
T.to('fd-tcaret', { opacity: 0, duration: .35, ease: 'steps(1)', repeat: 5, yoyo: true }, O8 + 0.2 / 2.05);
T.to('fd-tcaret', { opacity: 0, duration: .25, ease: 'power2.in' }, O8 + 3.6 / 2.05);
T.fromTo('fd-pwin', { opacity: 0, scale: .62, y: 10 }, { opacity: 1, scale: 1, y: 0, duration: .5 / 2.05, ease: 'power3.out' }, O8 + 0.1 / 2.05);
T.to('fd-pfill', { scaleX: .80, duration: 3.2 / 2.05, ease: 'none' }, O8 + 0.6 / 2.05);
T.to('fd-pknob', { left: (80 / 100) * 923.6, duration: 3.2 / 2.05, ease: 'none' }, O8 + 0.6 / 2.05);
// ref feature-discussion.html:173: t2 24→27 dur 3.2 @0.6 (inner ×2.05), Math.floor
for (var dk = 25; dk <= 27; dk++) { (function(dk) {
  T.set({ set: function(){ ctx.getNode('fd-ptime').text('0:' + dk + ' / 0:32'); } }, { opacity: 1 }, O8 + (0.6 + 3.2 * (dk - 24) / 3) / 2.05);
})(dk); }
// conversation `disc` timeline (authored 1×) is nested in `inner` (2.05×)
// then timeScale(2) → plays at 4.1×, so divide these events by 4.1.
T.to('fd-card', { opacity: 1, duration: .5 / 4.1, ease: 'power2.out' }, O8 + 0.5 / 4.1);
T.to('fd-chead', { opacity: 1, duration: .4 / 4.1, ease: 'power2.out' }, O8 + 0.9 / 4.1);
for (var r = 1; r <= 4; r++) {
  T.fromTo('fd-r' + r, { opacity: 0, scale: .96, y: 14 }, { opacity: 1, scale: 1, y: 0, duration: .42 / 4.1, ease: 'back.out(1.5)' }, O8 + 1.4 / 4.1 + (r - 1) * (0.4 / 4.1));
}
T.fromTo('fd-r5', { opacity: 0, scale: .96, y: 18 }, { opacity: 1, scale: 1, y: 0, duration: .5 / 4.1, ease: 'back.out(1.6)' }, O8 + 3.4 / 4.1);
var pairs = [['fd-p4o','fd-p4d'],['fd-p3o','fd-p3d'],['fd-p2o','fd-p2d'],['fd-p1o','fd-p1d']];
for (var pi = 0; pi < 4; pi++) {
  var pt = O8 + (4.2 + pi * 0.28) / 4.1;
  T.to(pairs[pi][0], { opacity: 0, duration: .2 / 4.1, ease: 'power2.in' }, pt);
  T.fromTo(pairs[pi][1], { opacity: 0, scale: .8 }, { opacity: 1, scale: 1, duration: .32 / 4.1, ease: 'back.out(1.7)' }, pt + .04 / 4.1);
}
T.fromTo('fd-merge', { opacity: 0, scale: .85, y: 10 }, { opacity: 1, scale: 1, y: 0, duration: .55 / 4.1, ease: 'back.out(1.6)' }, O8 + 5.9 / 4.1);
// feature-credits (2.54)
tw('cr-ttext', "SHOW YOUR CONTRIBUTOR", O9 + 0.3 / 2.54, 1.0 / 2.54, 'none');
T.to('cr-tcaret', { opacity: 0, duration: .4, ease: 'steps(1)', repeat: 7, yoyo: true }, O9 + 0.3 / 2.54);
T.to('cr-tcaret', { opacity: 0, duration: .3, ease: 'power2.in' }, O9 + 6.1 / 2.54);
